solutions.naive:
class Solution:
    def fib(self, n: int) -> int:
        if n < 2:
            return n
        return self.fib(n - 1) + self.fib(n - 2)

solutions.better:
class Solution:
    def fib(self, n: int) -> int:
        memo = {0: 0, 1: 1}

        def dfs(k: int) -> int:
            if k not in memo:
                memo[k] = dfs(k - 1) + dfs(k - 2)
            return memo[k]

        return dfs(n)

solutions.optimal:
class Solution:
    def fib(self, n: int) -> int:
        if n < 2:
            return n
        prev2, prev1 = 0, 1
        for _ in range(2, n + 1):
            prev2, prev1 = prev1, prev1 + prev2
        return prev1

